/* SHOPPER 11 · Bibliotecas conectadas, decisiones condicionadas y ayudas de confianza. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=c=>Number.isFinite(Number(c))?(Number(c)/100).toLocaleString('es-ES',{style:'currency',currency:'EUR'}):'—';
const dateEs=v=>v?new Date(v+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short'}):'Sin fecha';
const TYPES={actual:'Actual',semanal:'Semanal',mensual:'Mensual',ocasional:'Ocasional',evento:'Evento'};
const TOPICS={frescos:'Frescos',despensa:'Despensa',limpieza:'Limpieza',mascotas:'Mascotas',bebidas:'Bebidas',celebracion:'Celebración',salud:'Bienestar',otros:'Otros'};
const COVERS=['🧺','🥑','🥐','🍓','🍝','🧼','🐕','🎉','🍫','🌿','🏡','💐'];
const COLORS=['sage','peach','lavender','ocean','lemon','rose'];
const EMOJI={leche:'🥛',aceite:'🫒',huevo:'🥚',arroz:'🍚',pasta:'🍝',chocolate:'🍫',yogur:'🥣',galletas:'🍪',cafe:'☕',café:'☕',queso:'🧀',pan:'🥖'};
const ST={user:null,csrf:'',config:null,boot:null,baskets:[],basket:null,retail:[],retailInfo:null,view:'home',basketId:null,libraryFilter:'todas',chain:'Todas',cat:'Todas',search:'',activePlace:null,context:null,help:[],invite:new URLSearchParams(location.search).get('invite'),pendingProduct:null,modalType:null};
let noticeTimer=null,searchTimer=null,scrollY=0,basketStream=null;
function syncBasketStream(){
 if(basketStream){basketStream.close();basketStream=null}
 if(ST.view!=='basket'||!ST.user||!ST.basketId||!window.EventSource)return;
 const subscribed=ST.basketId;basketStream=new EventSource(`/api/baskets/${subscribed}/events`);
 basketStream.addEventListener('updated',()=>{if(ST.view==='basket'&&ST.basketId===subscribed){bootstrap().then(render).catch(()=>{})}});
 basketStream.addEventListener('revoked',()=>{basketStream?.close();basketStream=null;bootstrap().then(()=>chooseView('library')).catch(()=>{})});
}

function toast(msg,error=false){let el=$('#toast');el.textContent=msg;el.className='toast active'+(error?' error':'');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.className='toast',4400)}
async function api(path,method='GET',payload){const headers={'Accept':'application/json'};if(payload!==undefined)headers['Content-Type']='application/json';if(method!=='GET'&&ST.csrf)headers['X-Shopper-CSRF']=ST.csrf;
 let res;try{res=await fetch(path,{method,headers,credentials:'same-origin',cache:'no-store',body:payload===undefined?undefined:JSON.stringify(payload)})}catch{throw Error('No se ha podido conectar. Comprueba tu conexión.')}let out;try{out=await res.json()}catch{out={detail:'Respuesta inválida del servidor'}}if(!res.ok){let m=out.detail||'No hemos podido guardar el cambio';if(Array.isArray(m))m=m.map(x=>x.msg).join(' · ');throw Error(m)}return out}
function showModal(content){$('#modalInner').innerHTML=content;$('#modalBack').classList.remove('hidden');$('#modal').scrollTop=0}
function closeModal(){$('#modalBack').classList.add('hidden');$('#modalInner').innerHTML='';ST.modalType=null}
function needAccount(){if(ST.user)return true;openAuth('register');toast('Para guardar una cesta necesitas una cuenta');return false}
function title(kicker,t,desc,action=''){return `<div class="page-title"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(t)}</h1><p class="subline">${esc(desc)}</p></div>${action}</div>`}
function note(msg,warning=false){return `<div class="note ${warning?'amber':''}">${msg}</div>`}
function placeName(pid){return ST.boot?.places?.find(x=>x.id===pid)?.name||'Sin lugar asignado'}
function basketById(id){return ST.baskets.find(x=>x.id===Number(id))}
function currentBasket(){return basketById(ST.basketId)||ST.baskets.find(x=>x.kind==='actual'&&x.my_role==='owner')||ST.baskets[0]}
function storeBadge(chain){return `<span class="storebadge ${chain==='Carrefour'?'carrefour':chain==='DIA'?'':'other'}">${esc(chain==='Sánchez Romero'?'SR':chain.slice(0,3).toUpperCase())}</span>`}
function chooseView(view){ST.view=view;history.replaceState(null,'',view==='home'?'/':'/?view='+encodeURIComponent(view));render();syncBasketStream();window.scrollTo(0,0)}
async function bootstrap(){if(!ST.user)return;ST.boot=await api('/api/bootstrap');ST.baskets=ST.boot.baskets||[];if(!ST.baskets.some(x=>x.id===ST.basketId))ST.basketId=(ST.baskets.find(x=>x.kind==='actual'&&x.my_role==='owner')||ST.baskets[0])?.id||null;
 if(ST.activePlace&&!ST.boot.places?.some(p=>p.id===ST.activePlace))ST.activePlace=null;
 if(ST.basketId)await loadBasket();ST.help=ST.boot?.trusted_help_requests||[]}
async function loadBasket(){if(!ST.basketId){ST.basket=null;ST.context=null;return}ST.basket=await api('/api/baskets/'+ST.basketId);ST.context=await api('/api/baskets/'+ST.basketId+'/shopping-context')}
async function reload(){if(ST.user)await bootstrap();render()}
async function startup(){ST.config=await api('/api/config');ST.retailInfo=await api('/api/retail/catalog');ST.retail=ST.retailInfo.items||[];
 try{const r=await api('/api/auth/session');ST.user=r.user;ST.csrf=r.csrf;await bootstrap()}catch{ST.user=null;ST.csrf=''}
 const q=new URLSearchParams(location.search).get('view');ST.view=['home','library','basket','catalog','places','circle','pantry','account'].includes(q)?q:(ST.user?'home':'home');render();syncBasketStream();if(ST.invite){if(ST.user)promptInvite();else openAuth('register')}}
function shell(){ST.baskets=ST.boot?.baskets||ST.baskets;$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===ST.view));$('#currentPlaceName').textContent=ST.activePlace?placeName(ST.activePlace):'Mis lugares';$('#connectIndicator').textContent=ST.user?'● Cuenta privada':'● Explora sin registro'}
function render(){shell();let view={home:renderHome,library:renderLibrary,basket:renderBasket,catalog:renderCatalog,places:renderPlaces,circle:renderCircle,pantry:renderPantry,account:renderAccount}[ST.view]||renderHome;$('#main').innerHTML=view()}
function cover(b){return `<div class="cover ${esc(b.accent||'sage')}"><span class="emoji" aria-hidden="true">${esc(b.cover_emoji||'🧺')}</span><span class="cover-pill">${esc(TYPES[b.kind]||'Cesta')}</span></div>`}
function playlistCard(b){let place=b.place_id?placeName(b.place_id):'Sin lugar fijo';let topics=[];try{topics=JSON.parse(b.topics_json||'[]')}catch{}return `<article class="playlist" data-open-basket="${b.id}" tabindex="0" role="button" aria-label="Abrir cesta ${esc(b.title)}">${cover(b)}<div class="playlist-body"><h3>${esc(b.title)}</h3><p>${esc(place)}${b.kind==='evento'&&b.event_on?' · '+dateEs(b.event_on):''}</p>${topics.length?`<div class="mini-tags">${topics.slice(0,2).map(t=>`<span>${esc(TOPICS[t]||t)}</span>`).join('')}</div>`:''}<div class="playlist-foot"><span>${b.item_count||0} artículos</span><span>${b.my_role==='owner'?'Propia':'Compartida'} →</span></div></div></article>`}
function renderHome(){const own=ST.baskets.filter(b=>b.my_role==='owner');return `<section class="hero"><div><span class="eyebrow">LA COMPRA QUE ENCAJA CONTIGO</span><h1>Tus listas. Tus tiendas.<br><em>Tu gente.</em></h1><p>Haz la compra en segundos, reutiliza tus cestas favoritas y coordínate con quien quieras.</p><div class="row"><button class="btn primary" data-nav="library">▦ Abrir biblioteca</button><button class="btn soft" data-nav="catalog">⌕ Buscar productos</button></div></div><span class="hero-art" aria-hidden="true">🥑</span></section>
 <div class="statsbar"><div class="statbox"><strong>${ST.user?ST.baskets.length:'∞'}</strong><span>Cestas a tu manera</span></div><div class="statbox"><strong>${ST.boot?.places?.length||'⌖'}</strong><span>Lugares personales</span></div><div class="statbox"><strong>${ST.user?ST.boot?.friends?.length||0:'♡'}</strong><span>Personas de confianza</span></div></div>
 <div class="section-title"><div><h2>Tu biblioteca de compra</h2><p>Como tus playlists, pero para la vida real.</p></div>${ST.user?'<button data-action="newBasket" class="btn small primary">+ Crear cesta</button>':'<button data-action="register" class="btn small primary">Crear cuenta</button>'}</div>
 ${ST.user?(own.length?`<div class="board">${own.slice(0,6).map(playlistCard).join('')}</div>`:`<div class="empty"><div class="big">🧺</div><h3>Tu primera cesta</h3><button data-action="newBasket" class="btn primary">Crear</button></div>`):`<div class="three-choices"><div class="choice-card"><span>▦</span><h3>Cestas guardadas</h3><p>Tu compra semanal, tus recetas o tu fiesta: tantas como quieras.</p></div><div class="choice-card"><span>⌖</span><h3>Tu radio de tiendas</h3><p>Selecciona Casa, Oficina o Abuelos, y compara lo disponible en los datos.</p></div><div class="choice-card"><span>♡</span><h3>Comprar acompañados</h3><p>Listas compartidas y recados voluntarios entre contactos de confianza.</p></div></div>`}
 <div class="section-title"><div><h2>Productos de supermercados</h2><p>Una muestra de referencias publicadas por cadenas españolas.</p></div><button class="btn small soft" data-nav="catalog">Ver catálogo →</button></div>${note('<strong>Transparencia primero.</strong> Los precios de esta muestra pertenecen a una captura web del 23/11/2026. No son precios en tiempo real ni confirman stock en sucursales.',true)}<div class="product-grid mt16">${ST.retail.slice(0,6).map(productCard).join('')}</div>`}
function renderLibrary(){if(!ST.user)return title('TU MUNDO SHOPPER','Una biblioteca que crece contigo','Crea, guarda y comparte tu compra sin empezar de cero.')+guestCard();let fs=ST.baskets.filter(b=>ST.libraryFilter==='todas'||(ST.libraryFilter==='compartidas'?b.my_role!=='owner':b.kind===ST.libraryFilter)).filter(b=>!ST.activePlace||b.place_id===ST.activePlace||!b.place_id);
 return title('TU COLECCIÓN','Mis cestas','Crea listas como playlists: cada una para un momento y un lugar.',`<button class="btn primary" data-action="newBasket">+ Nueva cesta</button>`)+`<div class="library-filter">${[['todas','Todas'],['actual','Actual'],['semanal','Semanales'],['mensual','Mensuales'],['evento','Eventos'],['ocasional','Ocasionales'],['compartidas','Compartidas']].map(([k,v])=>`<button class="filter ${ST.libraryFilter===k?'selected':''}" data-library-filter="${k}">${v}</button>`).join('')}</div><div class="board">${fs.map(playlistCard).join('')}<button class="playlist" data-action="newBasket" aria-label="Crear nueva cesta"><div class="cover ocean"><span class="emoji">＋</span></div><div class="playlist-body"><h3>Crear otra colección</h3><p>Un lugar para lo que aún tienes en mente</p></div></button></div>`}
function guestCard(){return `<div class="empty"><div class="big">🧺</div><h3>Crea tu primera colección</h3><p>Podrás guardar listas, asignarles lugares y compartirlas con tu familia.</p><button class="btn primary" data-action="register">Crear cuenta</button><button class="btn soft" data-action="login">Ya tengo cuenta</button></div>`}
function basketItemsView(){const d=ST.basket;const b=d?.basket;const items=d?.items||[];let canwrite=d?.my_role!=='reader';
 const pantryActive=(ST.boot?.pantry||[]).filter(p=>p.state==='active').map(p=>String(p.product_name||p.custom_name||'').trim().toLowerCase());
 const duplicates=items.filter(i=>pantryActive.some(n=>n.length>3&&(String(i.name).toLowerCase().includes(n)||n.includes(String(i.name).toLowerCase()))));
return `<div class="card"><div class="basket-top"><span class="basket-icon">${esc(b?.cover_emoji||'🧺')}</span><div style="flex:1"><div class="eyebrow">${esc(TYPES[b?.kind]||'CESTA')}</div><h2>${esc(b?.title||'')}</h2><p class="muted small">${items.filter(i=>i.checked).length} de ${items.length} artículos · ${esc(b?.place_id?placeName(b.place_id):'Sin lugar fijo')}</p></div></div><div class="basket-progress"><span style="width:${items.length?Math.round(items.filter(i=>i.checked).length/items.length*100):0}%"></span></div>
 ${canwrite?`<form id="quickAdd" class="quick-form"><input class="input" name="title" required maxlength="120" placeholder="+ Apunta un producto…" aria-label="Producto para añadir"><button class="btn primary">Añadir</button></form>`:''}
 ${items.length?items.map(i=>`<div class="basket-item ${i.checked?'done':''}"><button data-action="itemCheck" data-kind="${i.item_kind}" data-item-id="${i.item_kind==='free'?i.free_id:i.product_id}" class="check ${i.checked?'done':''}" ${canwrite?'':'disabled'} aria-label="Marcar ${esc(i.name)}">${i.checked?'✓':''}</button><div class="itemtext"><div class="itemname">${esc(i.name)}</div><div class="itemmeta">${esc(i.format_text|| (i.item_kind==='free'?'Apunte rápido':'Producto del catálogo'))}</div></div><div class="qty"><button ${canwrite?'':'disabled'} data-action="itemQty" data-kind="${i.item_kind}" data-item-id="${i.item_kind==='free'?i.free_id:i.product_id}" data-qty="${Math.max(0,Number(i.quantity)-1)}" aria-label="Quitar unidad">−</button><b>${Number(i.quantity)}</b><button ${canwrite?'':'disabled'} data-action="itemQty" data-kind="${i.item_kind}" data-item-id="${i.item_kind==='free'?i.free_id:i.product_id}" data-qty="${Number(i.quantity)+1}" aria-label="Añadir unidad">+</button></div></div>`).join(''):`<div class="empty mt16"><div class="big">📝</div><h3>Tu lista comienza aquí</h3><p>Escribe cualquier artículo o explora los productos identificados.</p></div>`}
 ${duplicates.length?`<div class="note amber mt16"><strong>Antes de comprar:</strong> en tu despensa aparece algo parecido a ${esc(duplicates.slice(0,2).map(x=>x.name).join(' y '))}. Comprueba cantidades y formatos para no duplicar compras.</div>`:''}
 <div class="row mt16"><button class="btn soft small" data-nav="catalog">+ Buscar productos</button>${canwrite?'<button data-action="resetBasket" class="btn small">↺ Repetir lista</button>':''}${b?.kind!=='actual'&&canwrite?'<button data-action="copyToActual" class="btn small">Copiar a Actual</button>':''}</div></div>`}
function contextView(){const c=ST.context||{};const b=ST.basket?.basket;const canOwner=ST.basket?.my_role==='owner';return `<div class="stack"><div class="card"><h3>⌖ Dónde comprar esta cesta</h3><p class="subline">${esc(c.place?.name||'Esta cesta aún no tiene un lugar configurado')}</p>${!b?.place_id?note('Elige Casa, Oficina u otro lugar para usar su red de tiendas.'):c.stores?.length?`<div class="mt16">${c.stores.slice(0,5).map(s=>`<div class="row" style="margin-bottom:9px">${storeBadge(s.chain)}<div><strong>${esc(s.name)}</strong><div class="tiny muted">${esc(s.chain)}</div></div></div>`).join('')}</div>`:note('Este lugar todavía no tiene tiendas guardadas. Ve a Mis lugares para añadirlas.',true)}${canOwner?'<button class="btn soft block mt16" data-action="editBasket">Editar lugar y tiendas</button>':''}</div>
 <div class="card"><h3>Comparación prudente</h3><p class="subline">Cobertura de esta cesta en nuestra muestra de precios web.</p>${c.chains?.length?c.chains.map(x=>`<div class="row space mt16"><div><strong>${esc(x.chain)}</strong><div class="tiny muted">${x.coverage} de ${x.line_count} artículos identificados</div></div><div style="text-align:right"><strong>${x.comparable_total_cents===null?'—':euro(x.comparable_total_cents)}</strong><div class="tiny muted">${x.comparable_total_cents===null?'Sin total comparable':'Web · captura histórica'}</div></div></div>`).join(''):`<p class="subline mt16">Configura tu red de establecimientos para conocer qué cadenas podemos consultar.</p>`}<div class="note amber mt16">No mostramos un ahorro falso cuando faltan productos. Precios web de cadena fechados; descuentos y existencias locales sin confirmar.</div></div>
 <div class="card"><h3>Comparte o reutiliza</h3><p class="subline">Solo el propietario puede invitar y cambiar la configuración de la cesta.</p><div class="row mt16">${canOwner?'<button class="btn primary" data-action="shareBasket">♡ Invitar</button>':''}<button class="btn" data-action="duplicateBasket">Duplicar</button>${canOwner&&b?.kind!=='actual'?'<button class="btn" data-action="deleteBasket">Eliminar</button>':''}</div></div></div>`}
function renderBasket(){if(!ST.user)return title('MIS CESTAS','Tu compra, paso a paso','Empieza una lista y guárdala para repetirla.')+guestCard();let b=currentBasket();if(!b)return `<div class="empty">No tienes una cesta disponible.</div>`;if(ST.basket?.basket?.id!==b.id)return `<div class="empty">Cargando la cesta…</div>`;
 return `<div class="row space" style="margin-bottom:16px"><button class="btn small" data-nav="library">← Biblioteca</button>${ST.basket?.my_role==='owner'?'<button data-action="editBasket" class="btn small soft">✎ Personalizar</button>':''}</div><div class="basket-main">${basketItemsView()}${contextView()}</div>`}
function prodEmoji(it){let t=(it.name+' '+it.category).toLowerCase();for(const k in EMOJI){if(t.includes(k))return EMOJI[k]}return '🛒'}
function productCard(it){return `<article class="prod"><div class="prod-art"><span>${prodEmoji(it)}</span><small>${esc(it.chain)} · WEB</small></div><div class="prod-body"><div class="brand">${esc(it.brand||it.chain)}</div><h3>${esc(it.name)}</h3><span class="format">${esc(it.format||'Formato sin especificar')}</span><div class="prod-bottom"><div><strong>${euro(it.price_cents)}</strong><small>Web 23/11/2026</small></div><button data-action="addRetail" data-pid="${Number(it.product_id)}" title="Añadir a la cesta" aria-label="Añadir ${esc(it.name)}">+</button></div><a class="prod-source" href="${esc(it.source_url)}" target="_blank" rel="noopener noreferrer">Ver ficha de origen ↗</a></div></article>`}
function filteredCatalog(){let r=ST.retail.filter(x=>(ST.chain==='Todas'||x.chain===ST.chain)&&(ST.cat==='Todas'||x.category===ST.cat));if(ST.search)r=r.filter(x=>`${x.name} ${x.brand} ${x.category}`.toLowerCase().includes(ST.search.toLowerCase()));if(ST.activePlace){const links=ST.boot?.network||[];const stores=ST.boot?.stores||[];const ids=links.filter(x=>x.place_id===ST.activePlace).map(x=>x.store_id);const chains=new Set(stores.filter(s=>ids.includes(s.id)).map(s=>s.chain));r=r.filter(x=>chains.has(x.chain))}return r}
function renderCatalog(){let items=filteredCatalog(), cats=[...new Set(ST.retail.map(x=>x.category))].sort();let places=ST.boot?.places||[];return title('EL SUPERMERCADO EN TU BOLSILLO','Buscar productos','Productos identificados con fuente oficial; la disponibilidad física requiere verificación.')+`${note('<strong>Captura comercial identificada, no en directo.</strong> La red de tu lugar filtra cadenas, pero no demuestra que un producto esté en su sucursal. No existe integración de stock ni de ofertas en vivo.',true)}
 <div class="catalogbar"><input id="catalogSearch" class="input" placeholder="⌕ Buscar aceite, café, arroz…" value="${esc(ST.search)}"><select class="select" id="chainSelect" aria-label="Filtrar por cadena">${['Todas','DIA','Carrefour'].map(c=>`<option ${ST.chain===c?'selected':''}>${c}</option>`).join('')}</select><select class="select" id="catSelect" aria-label="Filtrar por categoría">${['Todas',...cats].map(c=>`<option ${ST.cat===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>
 <div class="row space" style="margin-bottom:15px"><div class="small muted"><strong>${items.length} referencias</strong> de nuestra muestra ${ST.activePlace?' · Lugar: '+esc(placeName(ST.activePlace)):''}</div>${ST.user&&ST.activePlace?'<button data-action="choosePlace" class="btn small">Cambiar lugar</button>':''}</div>
 ${items.length?`<div class="product-grid">${items.map(productCard).join('')}</div>`:`<div class="empty"><div class="big">⌕</div><h3>No aparecen referencias en este filtro</h3><p>${ST.activePlace?'Comprueba que hayas añadido tiendas DIA o Carrefour a tu red de este lugar.':'Prueba con otra búsqueda o categoría.'}</p><button data-action="resetFilters" class="btn soft">Restablecer filtros</button></div>`}`}
function renderPlaces(){if(!ST.user)return title('A TU ALREDEDOR','Lugares que importan','Distingue casa, oficina y familiares, sin mezclar tus supermercados.')+guestCard();let places=ST.boot?.places||[], stores=ST.boot?.stores||[], links=ST.boot?.network||[];return title('TU GEOGRAFÍA','Mis lugares','Guarda redes independientes de supermercados para cada lugar.',`<button data-action="newPlace" class="btn primary">+ Añadir lugar</button>`)+`<div class="grid2">${places.map(p=>`<div class="card"><div class="row space"><div><h3>⌖ ${esc(p.name)}</h3><p class="subline">${esc(p.address||'Dirección privada no indicada')}</p></div>${ST.activePlace===p.id?'<span class="pill">Activo</span>':''}</div><div class="mt16">${links.filter(l=>l.place_id===p.id).map(l=>`<span class="pill" style="display:inline-block;margin:0 4px 6px 0">${esc(stores.find(x=>x.id===l.store_id)?.name||'Tienda')}</span>`).join('')||'<span class="muted small">No hay tiendas vinculadas</span>'}</div><div class="row mt16"><button data-action="activatePlace" data-id="${p.id}" class="btn primary small">Usar lugar</button><button data-action="managePlace" data-id="${p.id}" class="btn small">Gestionar tiendas</button></div></div>`).join('')||`<div class="empty"><div class="big">🏠</div><h3>Crea Casa, Oficina o Abuelos</h3><p>Después podrás enlazar cestas y filtrar establecimientos.</p><button data-action="newPlace" class="btn primary">Crear mi primer lugar</button></div>`}</div>
 <div class="section-title"><div><h2>Avisos en tiendas · SHOPPER Live</h2><p>Aportes comunitarios con fecha. No son datos oficiales de inventario.</p></div></div>${(ST.boot.reports||[]).filter(r=>!ST.activePlace||(ST.boot.network||[]).some(l=>l.place_id===ST.activePlace&&l.store_id===r.store_id)).slice(0,5).map(r=>`<div class="storeentry"><span class="storebadge other">${r.kind==='repuesto'?'📦':r.kind==='agotado'?'⛔':r.kind==='descuento'?'🏷️':'🔔'}</span><div class="storebody"><strong>${esc(r.product_name)} · ${esc(r.kind)}</strong><small>${esc(r.store_name)} · ${esc(r.observed_at?.slice(0,16)||'')} · ${r.confirmations||0} confirmaciones</small></div>${r.i_confirmed?'✓':`<button class="btn small" data-action="confirmReport" data-id="${r.id}">Confirmar</button>`}</div>`).join('')||'<div class="note">Aún no hay avisos actuales de tus tiendas seleccionadas. Las notificaciones oficiales y el inventario en vivo requieren integraciones propias.</div>'}
 <div class="section-title"><div><h2>Directorio piloto</h2><p>Las fichas comerciales no garantizan inventario ni servicio de preparación.</p></div></div><div class="stack">${stores.slice(0,20).map(s=>`<div class="storeentry">${storeBadge(s.chain)}<div class="storebody"><strong>${esc(s.name)}</strong><small>${esc(s.address)}</small></div><span class="pill ${s.source_type==='aporte_manual_no_verificado'?'warn':'grey'}">${s.source_type==='aporte_manual_no_verificado'?'Sin verificar':'Directorio'}</span></div>`).join('')}</div><div class="row mt16"><button data-action="newStore" class="btn soft">+ Añadir tienda que falta</button><button data-nav="catalog" class="btn">Explorar catálogo ↗</button></div>`}
function renderPantry(){if(!ST.user)return title('APROVECHAR MÁS','Mi despensa','Recuerda qué tienes antes de volver a comprar.')+guestCard();const items=ST.boot?.pantry||[],active=items.filter(x=>x.state==='active');const soon=active.filter(x=>x.expires_on&&((new Date(x.expires_on+'T12:00:00')-new Date())/(864e5))<=5);return title('MENOS DESPERDICIO','Mi despensa','Antes de comprar, revisa qué queda en casa.',`<button class="btn primary" data-action="newPantry">+ Registrar alimento</button>`)+`<div class="statsbar"><div class="statbox"><strong>${active.length}</strong><span>Alimentos registrados</span></div><div class="statbox"><strong>${soon.length}</strong><span>Con fecha próxima</span></div><div class="statbox"><strong>${items.filter(x=>x.state==='discarded').length}</strong><span>Descartados registrados</span></div></div><div class="stack mt16">${active.length?active.map(x=>`<div class="storeentry"><span class="storebadge other">🥫</span><div class="storebody"><strong>${esc(x.product_name||x.custom_name||'Alimento')}</strong><small>${x.quantity} ${esc(x.unit)} ${x.expires_on?' · Fecha: '+dateEs(x.expires_on):''}</small></div><button class="btn small" data-action="consumePantry" data-id="${x.id}">Consumido ✓</button></div>`).join(''):`<div class="empty"><div class="big">🥑</div><h3>Despensa lista para empezar</h3><p>Registrar unos pocos alimentos te ayuda a evitar compras duplicadas.</p><button class="btn primary" data-action="newPantry">Añadir alimento</button></div>`}</div>${note('Las fechas y cantidades se introducen manualmente. No calculamos una reducción ambiental inventada.',true)}`}
function renderCircle(){if(!ST.user)return title('COMPRA ACOMPAÑADO','Mi círculo','Coordina compras y recados sin revelar tu ubicación a desconocidos.')+guestCard();let friends=ST.boot?.friends||[],helps=ST.help||[],owned=ST.baskets.filter(b=>b.my_role==='owner');return title('LA AYUDA ES CERCANA','Mi círculo','Una comunidad pequeña empieza con personas que se conocen.',`<button class="btn soft" data-action="friendInvite">+ Invitar amigo</button>`)+`${note('Las peticiones de ayuda solo se muestran a amistades aceptadas. No hay mapa público de personas vulnerables, ni se comparten direcciones automáticamente.')}
 <div class="grid2 mt16"><div class="card"><div class="row space"><h3>Mis contactos</h3><span class="pill">${friends.length}</span></div><div class="stack mt16">${friends.map(f=>`<div class="row"><span class="storebadge other">☺</span><div><strong>${esc(f.display_name)}</strong><div class="tiny muted">${esc(f.username)}</div></div></div>`).join('')||'<p class="subline">Invita a alguien mediante un enlace privado de un solo uso.</p>'}</div><div class="row mt16"><button data-action="friendInvite" class="btn soft small">Invitar a mi círculo</button><button data-action="redeem" class="btn small">Aceptar invitación</button></div></div>
 <div class="card soft"><h3>🤝 La compra de camino</h3><p class="subline">¿Puedes traer algo a una persona de confianza cuando vas al súper? Ofrece ayuda voluntaria de forma coordinada, sin pagos.</p><div class="row mt16"><button class="btn primary" data-action="askHelp">Pedir una mano</button></div></div></div>
 <div class="section-title"><div><h2>Peticiones de mi círculo</h2><p>Los contactos pueden aceptar voluntariamente los recados.</p></div></div><div class="grid2">${helps.map(r=>`<article class="card"><div class="row space"><strong>${esc(r.creator_name)}</strong><span class="pill ${r.status==='open'?'':'grey'}">${r.status==='open'?'Disponible':r.status==='accepted'?'En marcha':r.status==='done'?'Completado':'Cancelado'}</span></div><h3 class="mt16">${esc(r.note)}</h3><div class="small muted mt8">📍 ${esc(r.area_label)} ${r.needed_on?' · '+dateEs(r.needed_on):''}</div>${r.basket_title?`<div class="mini-tags mt8"><span>▦ ${esc(r.basket_title)}</span></div>`:''}${r.helper_name?`<p class="subline">Se encarga: ${esc(r.helper_name)}</p>`:''}<div class="row mt16">${r.status==='open'&&r.creator_id!==ST.user.id?`<button class="btn primary small" data-action="helpAction" data-id="${r.id}" data-status="accept">Puedo ayudarte</button>`:''}${r.status==='accepted'&&(r.creator_id===ST.user.id||r.helper_id===ST.user.id)?`<button class="btn primary small" data-action="helpAction" data-id="${r.id}" data-status="done">Marcar resuelto</button>`:''}${['open','accepted'].includes(r.status)&&r.creator_id===ST.user.id?`<button class="btn small" data-action="helpAction" data-id="${r.id}" data-status="cancel">Cancelar</button>`:''}</div></article>`).join('')||'<div class="empty"><div class="big">♡</div><h3>Sin solicitudes por ahora</h3><p>Cuando alguien de tu círculo pida ayuda, lo verás aquí.</p></div>'}</div>
 <div class="section-title"><div><h2>Compras familiares compartidas</h2></div></div><div class="row"><button class="btn soft" data-nav="library">Abrir cestas</button><button class="btn" data-action="redeem">Tengo un enlace de invitación</button></div>`}
function renderAccount(){return title('TODO EN UNA CUENTA','Mi perfil','Puedes cambiar de experiencia sin crear más cuentas.')+`<div class="grid2"><div class="card">${ST.user?`<h2>¡Hola, ${esc(ST.user.display_name)}!</h2><p class="subline">@${esc(ST.user.username)}</p><div class="statsbar"><div class="statbox"><strong>${ST.baskets.length}</strong><span>Cestas</span></div><div class="statbox"><strong>${ST.boot?.places?.length||0}</strong><span>Lugares</span></div><div class="statbox"><strong>${ST.boot?.friends?.length||0}</strong><span>Contactos</span></div></div><div class="row mt16"><button data-action="logout" class="btn">Cerrar sesión</button><a class="btn soft" href="/api/account/export">Exportar mis datos</a></div>`:`<h2>Entra en tu espacio</h2><p class="subline">Explora antes de registrarte; guarda cuando estés preparado.</p><div class="row mt16"><button data-action="register" class="btn primary">Crear cuenta</button><button data-action="login" class="btn soft">Entrar</button></div>`}</div><div class="card"><h3>SHOPPER, en tres facetas</h3><div class="stack mt16"><div>🧺 <strong>Comprar</strong> · Cestas y productos</div><div>⌖ <strong>Explorar</strong> · Tiendas y precios con fuentes</div><div>🤝 <strong>Ayudar</strong> · Círculo de confianza</div></div>${note('El acceso profesional para shoppers, los pagos y los pedidos a tiendas siguen deshabilitados hasta cumplir los requisitos legales y comerciales.',true)}<div class="row mt16"><a class="btn small" href="/classic">Funciones avanzadas ↗</a><a class="btn small" href="/health" target="_blank">Estado del servidor ↗</a></div></div></div>`}
function chooseIconList(selected){return `<div class="row" style="gap:6px" id="coverChoices">${COVERS.map(x=>`<label class="checkoption" style="padding:7px 9px"><input type="radio" name="cover_emoji" value="${x}" ${x===selected?'checked':''} required><span style="font-size:22px">${x}</span></label>`).join('')}</div>`}
function formPlaceOptions(place){return `<select class="select" name="place_id" id="basketPlace"><option value="">Sin lugar fijo</option>${(ST.boot?.places||[]).map(p=>`<option value="${p.id}" ${Number(place)===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`}
function storeOptionsForPlace(place,chosen=[]){if(!place)return `<div class="field-note">Elige un lugar para que aparezcan las tiendas que guardaste allí.</div>`;let ids=(ST.boot?.network||[]).filter(x=>x.place_id===Number(place)).map(x=>x.store_id);let stores=(ST.boot?.stores||[]).filter(x=>ids.includes(x.id));if(!stores.length)return `<div class="note amber">Aún no tienes tiendas en la red de este lugar. <button type="button" class="btn small" data-action="goPlaceNetwork" data-id="${place}">Configurar red ↗</button></div>`;
 return `<div class="checkgrid">${stores.map(s=>`<label class="checkoption"><input type="checkbox" name="preferred_store_ids" value="${s.id}" ${chosen.includes(s.id)?'checked':''}>${esc(s.name)} <span class="tiny muted">${esc(s.chain)}</span></label>`).join('')}</div><p class="field-note">Puedes marcar varias. Si no marcas ninguna, se usarán todas las tiendas de tu lugar.</p>`}
function basketEditor(b=null,details=null){if(!needAccount())return;let edit=!!b;let kind=b?.kind||'ocasional';let topics=[];try{topics=JSON.parse(b?.topics_json||'[]')}catch{}let place=b?.place_id||ST.activePlace||null;let chosen=details?.preferred_store_ids||[];const noPlaces=(ST.boot?.places||[]).length===0;
 ST.modalType=edit?'editBasket':'createBasket';showModal(`<div class="eyebrow">${edit?'PERSONALIZA TU COLECCIÓN':'ELIGE TU SIGUIENTE CESTA'}</div><h2>${edit?'Editar cesta':'Nueva cesta'}</h2><p>Las opciones se adaptan al tipo de cesta y al lugar que elijas.</p><form id="basketEditorForm" class="form mt16"><input type="hidden" name="basket_id" value="${edit?b.id:''}"><label>Nombre<input class="input" name="title" value="${esc(b?.title||'')}" required maxlength="90" placeholder="La compra de los domingos, Choc crave, Fiesta…"></label>
 <div class="form-grid"><label>Tipo de cesta<select class="select" name="kind" id="basketKind" ${kind==='actual'?'disabled':''}>${Object.entries(TYPES).filter(([k])=>k!=='actual'||kind==='actual').map(([k,v])=>`<option value="${k}" ${kind===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Presupuesto orientativo (€)<input class="input" type="number" name="budget_eur" min="0" max="50000" step=".01" placeholder="Opcional" value="${b?.budget_cents!==null&&b?.budget_cents!==undefined?(b.budget_cents/100).toFixed(2):''}"></label></div>
 <div id="eventOnly" class="conditional ${kind==='evento'?'':'hidden'}"><label>Fecha de la quedada o evento<input type="date" class="input" name="event_on" value="${esc(kind==='evento'?b?.event_on||'':'')}"></label><span class="field-note">Solo aparece en cestas de tipo Evento; una lista semanal no necesita fecha.</span></div>
 <label>Portada que reconocerás al instante</label>${chooseIconList(b?.cover_emoji||'🧺')}
 <label>Color de la colección</label><div class="row">${COLORS.map(x=>`<label class="checkoption" style="padding:8px 11px"><input type="radio" name="accent" value="${x}" ${x===(b?.accent||'sage')?'checked':''}><span class="cover ${x}" style="width:29px;height:25px;border-radius:7px"></span></label>`).join('')}</div>
 <label>¿Qué incluye? <span class="field-note">Puedes seleccionar varios temas</span></label><div class="checkgrid">${Object.entries(TOPICS).map(([k,v])=>`<label class="checkoption"><input type="checkbox" name="topics" value="${k}" ${topics.includes(k)?'checked':''}>${v}</label>`).join('')}</div>
 <label>Mi lugar ${noPlaces?'<span class="field-note">Primero crea uno en Mis lugares</span>':''}${formPlaceOptions(place)}</label>
 <label>Tiendas de este lugar <span class="field-note">Selección múltiple, dependiente del lugar</span></label><div id="basketStores">${storeOptionsForPlace(place,chosen)}</div>
 <label>Notas privadas de la cesta<textarea name="notes" class="input" maxlength="700" rows="2" placeholder="Preferencias, sustituciones, recordatorios…">${esc(b?.notes||'')}</textarea></label>
 <div class="form-controls"><button type="button" class="btn" data-action="closeModal">Cancelar</button><button class="btn primary" type="submit">${edit?'Guardar cambios':'Crear cesta'} →</button></div></form>`)}
function openAuth(mode){ST.modalType=mode;let reg=mode==='register';showModal(`<div class="eyebrow">UNA CUENTA PARA TODO</div><h2>${reg?'Empieza con SHOPPER':'Bienvenido otra vez'}</h2><p>Productos reales, cestas compartidas y tus lugares.</p><div class="row mt16"><button class="btn ${reg?'':'primary'}" data-action="login">Entrar</button><button class="btn ${reg?'primary':''}" data-action="register">Crear cuenta</button></div><form class="form mt16" id="${reg?'registerForm11':'loginForm11'}"><label>Usuario<input class="input" name="username" required minlength="3" maxlength="24" autocomplete="username" placeholder="tu_usuario"></label>${reg?'<label>Nombre visible<input class="input" name="display_name" minlength="2" maxlength="60" required placeholder="Cómo te llamamos"></label>':''}<label>Contraseña<input class="input" type="password" name="password" required minlength="${reg?12:1}" autocomplete="${reg?'new-password':'current-password'}"></label>${reg?`<label>Código privado de alta <span class="field-note">${ST.config?.signup_code_required?'Obligatorio':'Opcional en el modo local'}</span><input class="input" name="signup_code" autocomplete="off" ${ST.config?.signup_code_required?'required':''} placeholder="El configurado en Railway"></label>`:''}<button class="btn primary block" type="submit">${reg?'Crear mi cuenta':'Iniciar sesión'}</button></form><p class="field-note mt16">El código de registro no sustituye a tu contraseña. No compartas ninguno.</p>`)}
function openPlaceSelect(){if(!ST.user){needAccount();return}let opts=(ST.boot?.places||[]);showModal(`<div class="eyebrow">TUS SUPERMERCADOS LOCALES</div><h2>¿Para dónde compras?</h2><p>Tu selección filtra las cadenas visibles del catálogo, sin afirmar stock en tiendas físicas.</p><div class="stack mt16"><button class="btn block" data-action="activatePlace" data-id="0">Todos mis lugares</button>${opts.map(p=>`<button class="btn block" data-action="activatePlace" data-id="${p.id}">⌖ ${esc(p.name)}</button>`).join('')}<button class="btn primary block" data-action="newPlace">+ Crear un lugar nuevo</button></div>`)}
function openNewPlace(){if(!needAccount())return;showModal(`<div class="eyebrow">MI MAPA PERSONAL</div><h2>Añadir lugar</h2><p>Puedes llamarlo Casa Madrid, Oficina, Abuelos o como te sea más cómodo. La dirección es privada.</p><form class="form mt16" id="placeForm"><label>Nombre<input class="input" name="name" required minlength="2" maxlength="80" placeholder="Casa Madrid"></label><label>Dirección <span class="field-note">Opcional; no se comparte en el círculo</span><input class="input" name="address" maxlength="220" placeholder="Dirección privada"></label><button class="btn primary">Guardar lugar</button></form>`)}
function openStoreNetwork(id){if(!ST.user)return;const p=ST.boot.places.find(x=>x.id===Number(id));if(!p)return;let selected=new Set((ST.boot.network||[]).filter(x=>x.place_id===p.id).map(x=>x.store_id));showModal(`<div class="eyebrow">LA RED DE ${esc(p.name.toUpperCase())}</div><h2>Tus establecimientos</h2><p>Marca los supermercados que quieres incluir en las búsquedas de este lugar.</p><div class="stack mt16">${(ST.boot.stores||[]).slice(0,60).map(s=>`<div class="storeentry">${storeBadge(s.chain)}<div class="storebody"><strong>${esc(s.name)}</strong><small>${esc(s.address)}</small></div><button data-action="toggleStore" data-place="${p.id}" data-store="${s.id}" data-save="${selected.has(s.id)?'0':'1'}" class="btn small ${selected.has(s.id)?'soft':''}">${selected.has(s.id)?'✓ Guardada':'+ Añadir'}</button></div>`).join('')}</div>`)}
function openNewStore(){showModal(`<div class="eyebrow">AMPLÍA TU MAPA</div><h2>¿Falta un supermercado?</h2><p>Se guardará como aportación no verificada y sin atribuirle inventario.</p><form id="storeForm" class="form mt16"><label>Nombre<input class="input" name="name" required minlength="2" maxlength="100"></label><label>Cadena<input class="input" name="chain" required minlength="2" maxlength="80"></label><label>Dirección<input class="input" name="address" required minlength="6" maxlength="230"></label><button class="btn primary">Registrar establecimiento</button></form>`)}
function openHelpCreate(){if(!needAccount())return;showModal(`<div class="eyebrow">CÍRCULO DE CONFIANZA</div><h2>Pedir una mano</h2><p>Visible solo para amigos aceptados. No incluyas la dirección, el piso ni datos sensibles. Los detalles se coordinan fuera de este tablón.</p><form class="form mt16" id="helpForm"><label>Zona general<input class="input" name="area_label" required minlength="3" maxlength="70" placeholder="Madrid norte, Alcobendas…"></label><label>¿En qué necesitas ayuda?<textarea class="input" name="note" required minlength="4" maxlength="240" rows="3" placeholder="¿Alguien puede traer leche cuando vaya al súper?"></textarea></label><label>Vincular cesta (opcional)<select class="select" name="basket_id"><option value="">Sin cesta</option>${ST.baskets.filter(b=>b.my_role==='owner').map(b=>`<option value="${b.id}">${esc(b.title)}</option>`).join('')}</select></label><label>¿Para qué día? (opcional)<input class="input" type="date" name="needed_on"></label><button class="btn primary" type="submit">Publicar para mis amigos</button></form>`)}
function openNewPantry(){if(!needAccount())return;showModal(`<div class="eyebrow">APROVECHA LO QUE TIENES</div><h2>Registrar alimento</h2><form class="form mt16" id="pantryForm"><label>Alimento<input class="input" name="custom_name" required placeholder="Tomates, arroz, leche…" maxlength="100"></label><div class="form-grid"><label>Cantidad<input class="input" name="quantity" type="number" min="0.01" step="0.01" value="1" required></label><label>Unidad<select class="select" name="unit"><option value="ud">unidades</option><option value="kg">kg</option><option value="g">g</option><option value="l">l</option><option value="ml">ml</option></select></label></div><label>Consumir preferentemente antes de (opcional)<input class="input" type="date" name="expires_on"></label><button class="btn primary">Añadir a despensa</button></form>`)}
function showLinkInvite(code,label){let url=new URL(location.origin+'/');url.searchParams.set('invite',code);showModal(`<div class="eyebrow">COMPARTE EN PRIVADO</div><h2>${esc(label)}</h2><p>El enlace es de un solo uso y caduca a los 7 días. Solo envíalo a una persona de confianza.</p><input class="input mt16" readonly id="inviteLinkInput" value="${esc(url.toString())}"><button data-action="copyInvite" class="btn primary block mt16">Copiar enlace de invitación</button>`)}
function promptInvite(){if(!ST.invite)return;showModal(`<div class="eyebrow">INVITACIÓN DE SHOPPER</div><h2>¿Quieres aceptar?</h2><p>Al aceptarla, podrías incorporarte a una cesta compartida o conectar con una persona.</p><div class="row mt16"><button class="btn primary" data-action="acceptInvite">Aceptar invitación</button><button class="btn" data-action="dismissInvite">Ahora no</button></div>`)}
function manualRedeem(){showModal(`<div class="eyebrow">COMPRAS CON TU GENTE</div><h2>Aceptar invitación</h2><form class="form mt16" id="redeemForm"><label>Código recibido<input class="input" name="code" required minlength="15" placeholder="Pega aquí el código de invitación"></label><button class="btn primary">Aceptar</button></form>`)}
async function performAction(action,el){switch(action){
case 'register':openAuth('register');return;case 'login':openAuth('login');return;case 'closeModal':closeModal();return;
case 'logout':await api('/api/auth/logout','POST',{});ST.user=null;ST.csrf='';ST.boot=null;ST.baskets=[];ST.basket=null;ST.basketId=null;ST.activePlace=null;closeModal();chooseView('home');toast('Sesión cerrada');return;
case 'newBasket':basketEditor();return;case 'editBasket':basketEditor(ST.basket.basket,ST.basket);return;
case 'choosePlace':openPlaceSelect();return;case 'newPlace':openNewPlace();return;case 'managePlace':openStoreNetwork(el.dataset.id);return;
case 'goPlaceNetwork':closeModal();openStoreNetwork(el.dataset.id);return;
case 'activatePlace':ST.activePlace=Number(el.dataset.id)||null;closeModal();ST.chain='Todas';ST.cat='Todas';ST.search='';render();toast(ST.activePlace?'Lugar activado: '+placeName(ST.activePlace):'Viendo todos los lugares');return;
case 'toggleStore':await api('/api/places/'+el.dataset.place+'/stores','POST',{store_id:Number(el.dataset.store),save:el.dataset.save==='1'});await reload();openStoreNetwork(el.dataset.place);toast('Red de supermercados actualizada');return;
case 'newStore':openNewStore();return;
case 'confirmReport':await api('/api/live/'+el.dataset.id+'/confirm','POST',{});await reload();toast('Gracias por contrastar este aviso');return;
case 'resetFilters':ST.chain='Todas';ST.cat='Todas';ST.search='';render();return;
case 'addRetail':{let pid=Number(el.dataset.pid);if(!needAccount()){ST.pendingProduct=pid;return}let b=currentBasket();if(!b||b.my_role==='reader')throw Error('Selecciona una cesta editable');let q=ST.basket?.items?.find(i=>i.product_id===pid);await api(`/api/baskets/${b.id}/items/${pid}`,'PUT',{quantity:Number(q?.quantity||0)+1});await reload();toast('Añadido a «'+b.title+'»');return}
case 'itemQty':{let id=Number(el.dataset.itemId),qty=Number(el.dataset.qty);if(el.dataset.kind==='free'){await api(`/api/baskets/${ST.basketId}/free-items/${id}`,'PATCH',{quantity:qty})}else{await api(`/api/baskets/${ST.basketId}/items/${id}`,'PUT',{quantity:qty})}await reload();toast('Cantidad guardada');return}
case 'itemCheck':{let id=Number(el.dataset.itemId),item=(ST.basket.items||[]).find(i=>el.dataset.kind==='free'?i.free_id===id:i.product_id===id);if(!item)return;if(el.dataset.kind==='free')await api(`/api/baskets/${ST.basketId}/free-items/${id}`,'PATCH',{checked:!item.checked});else await api(`/api/baskets/${ST.basketId}/items/${id}/check`,'PATCH',{checked:!item.checked});await reload();return}
case 'resetBasket':await api(`/api/baskets/${ST.basketId}/reset-checks`,'POST',{});await reload();toast('Lista preparada para repetir');return;
case 'copyToActual':await api(`/api/baskets/${ST.basketId}/copy-to-actual`,'POST',{});await reload();toast('Copiada a la cesta Actual');return;
case 'duplicateBasket':{const r=await api(`/api/baskets/${ST.basketId}/duplicate`,'POST',{});ST.basketId=r.id;await reload();chooseView('basket');toast('Copia creada');return}
case 'deleteBasket':if(!confirm('¿Eliminar esta cesta?'))return;await api(`/api/baskets/${ST.basketId}`,'DELETE');ST.basketId=null;await reload();chooseView('library');toast('Cesta eliminada');return;
case 'shareBasket':{let r=await api(`/api/baskets/${ST.basketId}/invite`,'POST',{role:'editor'});showLinkInvite(r.code,ST.basket.basket.title);return}
case 'friendInvite':{let r=await api('/api/friends/invite','POST',{});showLinkInvite(r.code,'Invita a tu círculo');return}
case 'copyInvite':{let i=$('#inviteLinkInput');try{await navigator.clipboard.writeText(i.value);toast('Enlace copiado')}catch{i.select();toast('Selecciona el enlace y cópialo')};return}
case 'redeem':manualRedeem();return;
case 'acceptInvite':await api('/api/invitations/redeem','POST',{code:ST.invite});ST.invite=null;history.replaceState(null,'','/');closeModal();await reload();chooseView('library');toast('Invitación aceptada');return;
case 'dismissInvite':ST.invite=null;history.replaceState(null,'','/');closeModal();return;
case 'askHelp':openHelpCreate();return;
case 'helpAction':await api(`/api/circle/help/${el.dataset.id}/action`,'POST',{action:el.dataset.status});await reload();toast('Solicitud actualizada');return;
case 'newPantry':openNewPantry();return;
case 'consumePantry':await api(`/api/pantry/${el.dataset.id}`,'PATCH',{state:'used'});await reload();toast('Marcado como consumido');return;
default:return}}
function formObject(form){let fd=new FormData(form),obj={};for(let [k,v] of fd.entries()){if(obj[k]!==undefined){if(!Array.isArray(obj[k]))obj[k]=[obj[k]];obj[k].push(v)}else obj[k]=v}return obj}
function checkedValues(form,name){return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value)}
async function processForm(form){let x=formObject(form);switch(form.id){
case 'registerForm11':case 'loginForm11':{let reg=form.id==='registerForm11';let r=await api(reg?'/api/auth/register':'/api/auth/login','POST',{username:x.username,password:x.password,...(reg?{display_name:x.display_name,signup_code:x.signup_code||null}:{})});ST.user=r.user;ST.csrf=r.csrf;await bootstrap();closeModal();chooseView('library');toast(reg?'Cuenta creada':'¡Bienvenido!');if(ST.invite)promptInvite();else if(ST.pendingProduct){let p=ST.pendingProduct;ST.pendingProduct=null;await performAction('addRetail',{dataset:{pid:p}})}return}
case 'basketEditorForm':{let bid=Number(x.basket_id)||null;let payload={title:x.title.trim(),kind:x.kind||ST.basket?.basket?.kind||'ocasional',cover_emoji:x.cover_emoji||'🧺',accent:x.accent||'sage',topics:checkedValues(form,'topics'),place_id:x.place_id?Number(x.place_id):null,preferred_store_ids:checkedValues(form,'preferred_store_ids').map(Number),event_on:x.kind==='evento'?(x.event_on||null):null,budget_cents:x.budget_eur?Math.round(Number(x.budget_eur)*100):null,notes:x.notes||''};let r=bid?await api(`/api/baskets/${bid}`,'PATCH',payload):await api('/api/baskets','POST',payload);ST.basketId=bid||r.id;closeModal();await reload();chooseView('basket');toast(bid?'Cesta actualizada':'Cesta creada');return}
case 'quickAdd':{let t=String(x.title||'').trim();if(!t)throw Error('Escribe un artículo');await api(`/api/baskets/${ST.basketId}/free-items`,'POST',{title:t,quantity:1});await reload();$('#main #quickAdd input')?.focus();return}
case 'placeForm':{let r=await api('/api/places','POST',{name:x.name,address:x.address||null});ST.activePlace=r.id;closeModal();await reload();chooseView('places');toast('Lugar creado: añade sus tiendas');openStoreNetwork(r.id);return}
case 'storeForm':await api('/api/stores','POST',{name:x.name,chain:x.chain,address:x.address});closeModal();await reload();chooseView('places');toast('Tienda registrada sin verificación');return;
case 'helpForm':await api('/api/circle/help','POST',{area_label:x.area_label,note:x.note,needed_on:x.needed_on||null,basket_id:x.basket_id?Number(x.basket_id):null});closeModal();await reload();chooseView('circle');toast('Solicitud publicada solo a contactos aceptados');return;
case 'pantryForm':await api('/api/pantry','POST',{custom_name:x.custom_name,quantity:Number(x.quantity),unit:x.unit,expires_on:x.expires_on||null});closeModal();await reload();chooseView('pantry');toast('Alimento guardado');return;
case 'redeemForm':ST.invite=x.code.trim();await performAction('acceptInvite',{dataset:{}});return;
default:return}}
document.addEventListener('click',async event=>{let el=event.target.closest('[data-nav],[data-action],[data-open-basket],[data-library-filter]');if(!el)return;event.preventDefault();try{
 if(el.dataset.nav){chooseView(el.dataset.nav);return}
 if(el.dataset.openBasket){ST.basketId=Number(el.dataset.openBasket);await loadBasket();chooseView('basket');return}
 if(el.dataset.libraryFilter){ST.libraryFilter=el.dataset.libraryFilter;render();return}
 if(el.dataset.action)await performAction(el.dataset.action,el)
 }catch(e){toast(e.message,true)}});
document.addEventListener('keydown',async event=>{if(event.key==='Escape'){closeModal();return}if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-open-basket]')){event.preventDefault();ST.basketId=Number(event.target.dataset.openBasket);await loadBasket();chooseView('basket')}});
document.addEventListener('submit',async event=>{let form=event.target;if(!form.id)return;event.preventDefault();let btn=form.querySelector('button[type=submit],button:not([type])');if(btn)btn.disabled=true;try{await processForm(form)}catch(e){toast(e.message,true)}finally{if(btn&&btn.isConnected)btn.disabled=false}});
document.addEventListener('change',event=>{let x=event.target;
 if(x.id==='basketKind'){let box=$('#eventOnly');if(box){box.classList.toggle('hidden',x.value!=='evento');if(x.value!=='evento'){let d=box.querySelector('[name="event_on"]');if(d)d.value=''}}}
 if(x.id==='basketPlace'){$('#basketStores').innerHTML=storeOptionsForPlace(x.value,[])}
 if(x.id==='chainSelect'){ST.chain=x.value;render()}
 if(x.id==='catSelect'){ST.cat=x.value;render()}
});
document.addEventListener('input',event=>{if(event.target.id==='catalogSearch'){let v=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{ST.search=v;render();let i=$('#catalogSearch');i?.focus();i?.setSelectionRange(v.length,v.length)},250)}});
$('#closeModal').addEventListener('click',closeModal);$('#modalBack').addEventListener('click',e=>{if(e.target.id==='modalBack')closeModal()});$('#accountButton').addEventListener('click',()=>chooseView('account'));$('#placeSwitch').addEventListener('click',openPlaceSelect);
window.addEventListener('offline',()=>toast('Estás sin conexión. No se guardarán cambios.',true));window.addEventListener('online',()=>toast('Conexión restablecida'));
startup().catch(e=>{$('#main').innerHTML=`<div class="empty"><div class="big">⚠️</div><h3>No hemos podido abrir SHOPPER</h3><p>${esc(e.message)}</p><button class="btn primary" onclick="location.reload()">Reintentar</button></div>`});
